-- ═══════════════════════════════════════════════════════════════════
-- migration_passions_plat — PARTIE 2 / 7
-- ───────────────────────────────────────────────────────────────────
-- Coller les parties DANS L'ORDRE, une par une, en attendant que chacune
-- réponde avant de passer à la suivante.
-- Chaque partie est sa propre transaction et le miroir est IDEMPOTENT :
-- si une partie échoue, corriger puis la relancer, sans reprendre depuis
-- la première.
-- ═══════════════════════════════════════════════════════════════════
begin;


on conflict (id) do update set
  label = excluded.label,
  normalized_label = excluded.normalized_label,
  aliases = excluded.aliases,
  status = case when public.passions.status = 'archived' then public.passions.status else excluded.status end,
  source = case when public.passions.source = 'legacy' then 'legacy' else excluded.source end,
  is_broad = excluded.is_broad,
  popularity = excluded.popularity,
  sort_order = excluded.sort_order,
